create table if not exists public.mission_rescue_cases(id uuid primary key default gen_random_uuid(),job_id uuid not null references public.marketplace_jobs(id) on delete cascade,status text not null default 'open' check(status in('open','resolved','cancelled')),reason text not null,severity text not null check(severity in('WATCH','ACTION REQUIRED','CRITICAL')),recommended_agency_id uuid references public.agencies(id),opened_by uuid not null references public.profiles(id),opened_at timestamptz not null default now(),resolved_at timestamptz,notes text);
create unique index if not exists mission_rescue_cases_one_open_idx on public.mission_rescue_cases(job_id) where status='open';
alter table public.mission_rescue_cases enable row level security;
drop policy if exists mission_rescue_cases_owner_read on public.mission_rescue_cases;
create policy mission_rescue_cases_owner_read on public.mission_rescue_cases for select using(public.current_role()='platform_admin');
create or replace function public.start_mission_rescue(p_job_id uuid,p_reason text,p_severity text,p_recommended_agency_id uuid default null) returns jsonb language plpgsql security definer set search_path=public set row_security=off as $$ declare v public.mission_rescue_cases; begin if public.current_role()<>'platform_admin' then raise exception 'PLATFORM_ADMIN_REQUIRED'; end if; if p_severity not in('WATCH','ACTION REQUIRED','CRITICAL') then raise exception 'INVALID_RESCUE_SEVERITY'; end if; if not exists(select 1 from public.marketplace_jobs where id=p_job_id and status in('accepted','assigned','active')) then raise exception 'MISSION_NOT_RESCUABLE'; end if; if p_recommended_agency_id is not null and not exists(select 1 from public.agencies where id=p_recommended_agency_id and status='approved') then raise exception 'BACKUP_AGENCY_NOT_APPROVED'; end if; insert into public.mission_rescue_cases(job_id,reason,severity,recommended_agency_id,opened_by) values(p_job_id,p_reason,p_severity,p_recommended_agency_id,auth.uid()) on conflict(job_id) where status='open' do update set reason=excluded.reason,severity=excluded.severity,recommended_agency_id=excluded.recommended_agency_id,notes=null returning * into v; insert into public.mission_events(job_id,actor_user_id,event_type,payload) values(p_job_id,auth.uid(),'operations_rescue_started',jsonb_build_object('rescue_case_id',v.id,'severity',p_severity,'reason',p_reason,'recommended_agency_id',p_recommended_agency_id)); insert into public.owner_audit_log(actor_user_id,action,target_type,target_id,payload) values(auth.uid(),'mission_rescue_started','marketplace_job',p_job_id,jsonb_build_object('rescue_case_id',v.id,'severity',p_severity,'recommended_agency_id',p_recommended_agency_id)); return to_jsonb(v); end $$;
revoke all on function public.start_mission_rescue(uuid,text,text,uuid) from public,anon;
grant execute on function public.start_mission_rescue(uuid,text,text,uuid) to authenticated;
